message.content:
{
  "report_1": "Cedar United held discussions with Alex Stone and his representatives on Monday, after training, with club officials present. City Wire initially described the talks as an agreement, but later corrected its report: no contract was offered and no deal was reached."
}

{
  "report_1": "On Monday, the Cedar Comets defeated the Vale Stars 108–104. Jordan Reed scored 27 points. The team indicated Reed is questionable for Wednesday due to ankle soreness."
}

{
  "report_1": "Cedar United beat Vale City 2–1 on Sunday. Sam Lee scored the winner in the 84th minute."
}

{
  "report_1": "Cedar United are reportedly in talks to sign Alex Stone, according to two unnamed sources. No agreement has been reached. Cedar United declined to comment."
}
